INSERT INTO "crop_catalog" ("id", "name", "description", "category_id", "known_for", "num_field_inspection_needed", "isolation_distance", "preferred_ecological_zone_id") VALUES
  (1, 'Maize ( Zea mays L.)', 'It was introduced to Ethiopia in 16th or 17th century.  It is grown in most parts of the
world over a wide range of environmental conditions, ranging between
500 latitudes north and south of equator. It also grows from sea level to
over 3000 meters above sea level.
In Ethiopia, maize grows from moisture stress areas to high rainfall
areas and from lowlands to the highlands. It is largely produced in
Western, Central, Southern and Eastern parts of the country', 1, 'Hybrid and Composite type which are used as staple food and others', 2, 300, 2),
  (2, 'Bread wheat (Triticum aestivum L.)', 'Bread Wheat is one of the major cereal crops in the Ethiopian highlands, which range
between 6 and 16°N, 35 and 42°E, and from 1500 to 2800 m. 
Altitude plays an important role in the distribution of wheat production
through its influence on rainfall, temperature, and diseases. In Arsi,
Bale and Shewa regions, the soil, moisture and disease conditions
within the range of 1900-2300m altitude zone are favorable for the
production of early and intermediate maturing varieties of bread wheat.', 1, 'Specially for bread preparation ,  It is the major cereal crop', 5, 3, 2),
  (3, 'Durum Wheat', 'Triticum turgidum var.durum . 
Durum or macaroni wheat is indigenous to Ethiopia and it has been
under cultivation since ancient times. Ethiopia is considered to be the
center of genetic diversity of this crop. It is a tetraploid wheat species
and traditionally grown on heavy black clay soils (Vertisols) of the
central and northern highlands of Ethiopia between 1800-2800 meters
above sea level.', 1, 'To make spaghetti, macaroni and other  pastas.', 5, 3, 2),
  (4, 'Food Barley', 'Hordeum vulgare', 1, 'The crop is now grown worldwide with  greater concentration in temperate areas and high altitudes of the  tropics and subtropics', 0, 0, NULL),
  (5, 'Malt Barley', 'Hordeum distichon', NULL, 'The major (90%) raw material for beer  production. Characterized as two-rowed and six rowed barley in  which only the middle spiklet of each three produces seed, the other  two being sterile or male', 0, 0, NULL),
  (6, 'Tef ( Eragrostis tef)', 'Tef is a gluten-free an important cereal crop in Ethiopia. It is the most adapted crop in the diverse
agro-ecologies of the country.', 1, 'Tef is a gluten-free an important cereal crop in Ethiopia.', 2, 5, NULL),
  (7, 'Sorghum (Sorghum bicolor)', 'Sorghum is one of the major crops produced in Ethiopia, and it is the
fourth important crop in terms of area coverage and volume of
production. It is adapted to a wide range of environment, and hence
can be produced in the high lands, medium altitude and low land areas.
It is widely produced more than any other crops, in the areas where
there is moisture stress.', 1, 'cultivated for its edible grain, Sweet sorghums are sorghum cultivars that are primarily grown for  foliage; they are shorter than those grown for grain.', 4, 200, NULL),
  (8, 'Millet', '', NULL, 'Soil acidity tolerant', 0, 0, NULL),
  (9, 'Rice', 'Oryza sativa L. or Oryza glaberrima', NULL, 'Paddy Agriculture', 0, 0, NULL),
  (10, 'Finger Millet', 'Eleusine coracana', NULL, 'Liquor', 2, 3, NULL),
  (12, 'Triticale', 'X-Triticosecale', NULL, 'Tolerant of soil acidity', 0, 0, NULL),
  (13, 'Emmer wheat (Aja)', 'Triticum dicoccum', NULL, 'Maternal care', 2, 3, NULL),
  (14, 'Buck wheat', 'Buck wheat (Fagopyrum esculentum Monench) is a recent introduction
where its cultivation and use is new to Ethiopia. It is relatively low
yielder compared to other grain crops, however, its unique characters
such as its ability to perform better relatively on poor soils and its quick
maturity, suiting areas with very short rains and as a catch crop where
other crops failed or planting is delayed, makes it important.', 10, 'Is a recent introduction  where its cultivation and use is new to Ethiopia', 3, 3, 1),
  (15, 'Pearl millet', 'Pennisetum glaucum (L.)R. Br.', NULL, 'production systems characterized by  drought, low soil fertility, and high temperature', 0, 0, NULL),
  (16, 'Foxtail millet', 'Setaria italic', NULL, 'It performs well in  soils with high salinity or low pH. Because of its tolerance to difficult  growing conditions, it can be grown in areas where other cereal crops,  such as maize or wheat, would not survive.', 0, 0, NULL),
  (17, 'Quinoa', 'Chenopodium quinoa Willd', NULL, 'Gibito', 0, 0, NULL),
  (18, 'Food oat', 'Avena sativa', NULL, 'Food', 0, 0, NULL),
  (19, 'Faba bean', 'Vicia faba', NULL, 'It is widely used for food and has high protein content. Due to its  nitrogen fixing capacity it is used in crop rotation.', 2, 0, NULL),
  (20, 'Field pea', 'Pisum sativum', 2, 'It is widely used for food because of its highest protein contents', 2, 3, NULL),
  (21, 'Dekoko', 'Pisum sativum var. abyssinicum', NULL, 'Dekoko is a pulse crop cultivated and developed in Ethiopia', 0, 0, NULL),
  (22, 'Chickpea', 'Cicer arietinum', NULL, 'Two types of chickpea produced globally, namely desi and  kabuli chickpeas. Kabuli chickpeas have a larger cream-colored seed  with a thin seed coat whereas the desi type has a smaller', 2, 3, NULL),
  (23, 'Cowpea', 'Vigna ungulculata', NULL, 'Can be  grown in relatively infertile sandy soils with a minimum annual rainfall  of 200mm. It is a fast growing, drought resistant crop.', 2, 3, NULL),
  (24, 'Lentil', 'Lens culinaris.', NULL, 'Largely produced in the highland & semi-highland regions of the  country mainly on clay soil.', 2, 0, NULL),
  (25, 'Common/Haricot/ bean', 'Phaseolus vulgare', 2, 'Haricot bean also known as common bean is an herbaceous annual  plant domesticated independently in ancient Mesoamerica and the  Andes, and now grown worldwide for its edible bean, popular both dry  and as a green bean', 2, 0, NULL),
  (26, 'Soybean', 'Glycine max', NULL, 'Is classed as an oilseed and  pulse. Fat-free (defatted) soybean meal is a primary, low-cost, source  of protein for animal feeds and most prepackaged meals; soy vegetable  oil is another valuable product of processing the soybean crop', 2, 3, NULL),
  (27, 'Grass pea/ ''''Guaya''''', 'Lathyrus sativus L.', NULL, 'It is the cheapest source of protein in the diets of most  people', 0, 0, NULL),
  (28, 'Mung bean', 'Vigna radiata L', NULL, 'Mung bean is an ancient and well-known crop in Asia. It is often  included in rice or wheat-based cropping systems in the tropics and  subtropics', 0, 0, NULL),
  (29, 'Fenugreek', 'Trigonella foenum-graecum', NULL, 'Fenugreek is a plant in the family of Fabaceae. It is used both as an  herb (the leaves) and as a spice (the seed).', 0, 0, NULL),
  (30, 'Noug', 'Guizotia abyssinica L.', NULL, 'Noug is an oil-seed crop, indigenous to Ethiopia and holds significant  promise for improving rural livelihoods in Sub-Saharan Africa. The  species is used in intercropping systems, grows on poor but also  extremely wet soils, and contributes to soil conservation', 2, 600, NULL),
  (31, 'Linseed', 'Linum usitatissimum L.', NULL, 'It is the second most important oil crop after Noug.', 2, 200, NULL),
  (32, 'Rapeseed', 'Brassica spp.', NULL, 'Ground seeds are used to grease a bread-baking clay pan,  cure certain ailments or stomach upsets and prepare beverages; the  leaves of young plants are good source of vegetable relish. The oil,  very often adulterated with the premium oil from noug is the  commercial product', 2, 200, NULL),
  (33, 'Sesame', 'Sesamum indicum.', 3, 'Sesame is used for food. The dried seeds are eaten in soups and, mixed  with sugar, are a popular sweet in Africa and Asia. It is used as a salad  and cooking oil. The oil is also used in the manufacture of margarine  and compound cooking fats', 2, 50, NULL),
  (34, 'Groundnut', 'Arachis hypogaea', NULL, 'It is a major  cash crop and widely grown in all the tropical and sub tropical regions  of the world for direct use as food, oil, and high protein meal.', 2, 0, NULL),
  (35, 'Sunflower', 'Helianthus annuus', NULL, 'Sunflower oil, extracted from the seeds, is used for cooking, as carrier  oil and to produce margarine and bio-diesel, as it is cheaper than olive  oil.', 2, 0, NULL),
  (36, 'Safflower', 'Carthamus tinctorius L.', NULL, 'This herb is  highly branched with many long sharp spines on the leaves. Plants are  generally 30 to150 cm tall with globular flower heads (capitula) and  commonly, brilliant yellow, orange or red flowers. It is widely grown  for its red or orange flower heads and seeds that yield valuable oil.', 2, 50, NULL),
  (37, 'Vernonia', 'Vernonia galamensis', NULL, 'Vernonia galamensis is a new potential industrial crop with very high  content of vernolic acid in the seed oil. The products that can be made  from vernonia include epoxies for manufacturing adhesives, varnishes  and paints, and industrial coatings.', 0, 0, NULL),
  (38, 'Castor', 'Ricinus communis L', NULL, 'Castor seed is  the source of castor oil, which has a wide variety of uses. The seeds  contain between 40% and 60% oil that is rich in triglycerides, mainly  ricinolein. The seed contains ricin, a toxin, which is also present in  lower concentrations throughout the plant.', 0, 0, NULL),
  (39, 'Camelina sativa', 'Camelina sativa', NULL, 'The crop has multitude of uses  among which its edible oil being the major one. The seed oil of  Camelina contains an exceptional amount (up to 45 per cent) of omega3 fatty acids, as well as a unique antioxidant complex making the oil  very stable and resistant to heat and rancidity. Unlike any other omega3 oil, Camelina oil is perfectly suitable for use not only as a well  balanced omega-3 supplement, but also as a health promoting everyday  cooking oil.', 0, 0, NULL),
  (40, 'Irish potato', 'Solanum tuberosum', NULL, 'It was  introduced to Ethiopia in 1858 and since then it has become an  important crop in many parts of the country. In volume of  production it ranks fourth in the world after maize, rice, and wheat.  Among root crops, potato ranks first in volume produced and  consumed, followed by cassava, sweet potato, and yam.', 0, 0, NULL),
  (41, 'Sweet potato', 'Ipomoea batatas', NULL, 'Its large, starchy, sweet tasting tuberous roots are an  important root vegetable. The young leaves and shoots are sometimes  eaten as greens. It is one of the major root crops of Ethiopia, which is  cultivated around home for several years and is used for food and feed.', 0, 0, NULL),
  (42, 'Taro', 'Colocasia esculenta', NULL, 'It is a root crop of secondary importance grown in many parts of the  wet tropics, and does best on a moist or even slightly swampy soil. It is  known as taro in the Pacific Islands, eddo or dasheen in the West  Indies, as old cocoyam in West Africa and „Godere‟ in Ethiopia.', 0, 0, NULL),
  (43, 'Cassava', 'Manihot esculenta', NULL, 'The  carbohydrate rich but low in protein storage roots represent an  important energy source and are a staple food stuff for more than 500  million people throughout tropical Africa, Latin America and parts of  Asia. Cassava can grow under poor soil conditions and can withstand  drought. It is therefore usually considered as an important famine  reserve crop in countries with unreliable rainfall.', 0, 0, NULL),
  (44, 'Enset', 'Ensete ventricosum (Welw.) Cheesman', NULL, 'It is Ethiopia''s most important root  crop, a traditional staple crop in the densely populated south and  southwestern parts of Ethiopia. Enset provides more amount of food  stuff per unit area than most cereals.', 0, 0, NULL),
  (45, 'Yam', 'Dioscorea spp', NULL, 'This  thick, tropical-vine tuber is popular in Africa, the West Indies, and  parts of Asia, South and Central America. By virtue of its excellent  palatability, it is a high value crop. Yams are cultivated throughout the  tropics, and in parts of the sub-tropics and temperate zones. In West  Africa and New Guinea, the yam is a primary agricultural commodity.', 0, 0, NULL),
  (46, 'Tomato', 'Lycopersicum esculentum.Mill', NULL, 'It is an important cash-generating crop to small scale farmers and provides employment in the production and  processing industries. It is also important source of vitamin A and C as  well as minerals', 2, 0, NULL),
  (47, 'Garlic', 'Allium Sativum.', NULL, 'Garlic is used as a seasoning in many foods worldwide, without garlic  many of our popular dishes would lack the flavor and character that  make them favorites. Garlic''s volatile oil has many sulfur containing  compounds that are responsible for the strong odor, its distinctive  flavor and pungency as well as for its healthful benefits.  Medicinal activity seems to be highest in fresh garlic or garlic oil with  high allicin content.', 0, 0, NULL),
  (48, 'Onion', 'Allium cepa L.', NULL, 'It is considerably important in the  daily Ethiopian diet. All the plant parts are edible, but the bulbs and the  lower stems sections are the most popular as seasonings or as  vegetables in stews.', 0, 0, NULL),
  (49, 'Shallot', 'Allium cepa var. asculonicum Barker; syn.   A. ascalonicum auct. non L.', NULL, 'widely cultivated as a source of income by  peasant farmers in many parts of the Ethiopia. They have a wide range  of climatic and soil adaptation and are cultivated both under rain-fed  and irrigated conditions. They are grown primarily for the bulb,  although the green tops may also be consumed.', 0, 0, NULL),
  (50, 'Sweet/Hot Pepper', 'Capsicum annum) and Chili  (Capsicum frutenscens', NULL, 'It is one of the most important  vegetable crops for fresh consumption (as chilies), for processing and  as a spice (for making stew). It is also a very important crop for spice  extraction since it has a lot of Oleoresin for dying of food items', 0, 0, NULL),
  (51, 'Cabbage', 'Brassica oleracea', NULL, 'Cabbage is alkaline in reaction, high in cellulose or roughage, and has  very low calorie content and is very effective in helping overcome  constipation, and sauerkraut, or sauerkraut juice, is particularly good  for a sluggish intestinal tract, and for more serious cases of  constipation', 0, 0, NULL),
  (52, 'Carrot', 'Daucus carota L.', NULL, 'Carrot is particularly rich in carotene (pro-vitamin A). It is consumed  either fresh, as a salad crop, or cooked.', 0, 0, NULL),
  (53, 'Okra', 'Abelmoschus esculentus L. Monech', NULL, 'Okra is especially valued for its tender delicious fruits and is agood  source of iodine and calcium. Apart from its nutritive value, matured  fruits and stems containing crude fiber are used in paper industry. It can  be eaten grated raw or cooked. It possesses high nutritive value.', 0, 0, NULL),
  (54, 'Anchote', 'Coccinia abyssinica', 5, 'It is a good source of vitamins, minerals protein and  calcium compared to other root crops. Therefore, it can be used as a  strategic crop to alleviate protein deficiency in areas of nutrition with  low protein source (Amsalu et al., 2008).The most widely used  vernacular name is Anchote, spelt ''Ancootee '' in Oromo. It is also  called: Ushushe (Wolaita), Shushe (Dawuro), and Ajjo (Kafigna)  (Amsalu et al., 2008).', 0, 0, NULL),
  (55, 'Summer squash', 'Cucurbita pepo', NULL, 'The entire  vegetable, including its flesh, seeds and skin, is edible. In addition,  some varieties of the squashes produce edible flowers. Unlike winter  squash, summers squash is more fragile and cannot be stored for long  period of time.', 0, 0, NULL),
  (56, 'Summarsquash', 'Cucurbita pepo', NULL, 'Is a recent introduction and  cultivation to Ethiopia. Summer squash, members of the Cucurbitaceae  family and relatives of both the melon and the cucumber, come in  many different varieties. While each type varies in shape, color, size  and flavor, they all share some common characteristics. The entire  vegetable, including its flesh, seeds and skin, is edible.', 0, 0, NULL),
  (57, 'Coriander', 'Coriandrum sativum L.', NULL, 'Spice', 0, 0, NULL),
  (58, 'Black pepper', 'Piper nigrum L.', NULL, 'Spice', 0, 0, NULL),
  (59, 'Ginger', 'Zingeber officinale Rosc', NULL, 'Spice', 0, 0, NULL),
  (60, 'Turmeric', 'Curcuma domestica', NULL, 'Spice', 0, 0, NULL),
  (61, 'Cardamom', 'Elettaria cardamomum', NULL, 'Spice', 0, 0, NULL),
  (62, 'Sweet annie', 'Artemisia annua', NULL, 'Spice', 0, 0, NULL),
  (63, 'Citronella grass', 'Cymbopogon winteranius', NULL, 'Spice', 0, 0, NULL),
  (64, 'Pyrethrum', 'Chrysanthemum cinerariaefolium', NULL, 'Spice', 0, 0, NULL),
  (65, 'Cumin', 'Nigella sativa', NULL, 'Spice', 0, 0, NULL),
  (66, 'Lemmon grass', 'Cymbopogon citratus (DC) Stapf)', NULL, 'Can be used as carminative, insect repellant and widely  used as herbal tea. It has a remedial properties and is used to treat  bronchitis, sinusitis, cold, fever, malaria, hemorrhoids, toothache, baby  oil, massage oil, ointment for body, oil for rheumatism, oil for beauty  mask, herbal baths, sop and candle making industries and herbal  cooking‟s', 0, 0, NULL),
  (67, 'Speare mint', 'Mentha spicata L.', NULL, 'Among mint species, spearmint (Mentha spicata L.) is considered industrial crop as it is a source of essential oils  enriched in certain monoterpenes like carvol, dihydrocarveole,  dihydrocarveylacetate, menthol, menthone, caryophyllene, terpineol  and cubebene which is widely used in food, flavor, cosmetic and  pharmaceutical industries.', 0, 0, NULL),
  (68, 'Spanish mint', 'Mentha spicata ''Spanish Pointed''', NULL, 'A full-flavored mint use Spanish mint in tea,  soups, stirs fry, salads and more. It is used in teas, beverages, jellies,  syrups, ice creams, confections, chutneys.', 0, 0, NULL),
  (69, 'African marigold', 'Tagetes erecta L.', NULL, 'African marigold (Tagetes erecta L.) is a  widely cultivated as bedding plants, loose flower, perfume, natural  color, pigments, carotinoids, insect and nematodes repellents, nutrient  supplement for poultry feed.', 0, 0, NULL),
  (70, 'Rose Scented Geranium', 'Pelargonium graveolens L. Herit', NULL, 'The essential oil has wide-ranging uses in flavor and fragrance  industries, aromatherapy, cosmetic industries, food and pharmaceutical  industries.', 0, 0, NULL),
  (71, 'Chamomile', 'Matricaria chamomilla L.', NULL, 'It is a well-known aromatic and medicinal  plant often referred to as the “star among medicinal species”.', 0, 0, NULL),
  (72, 'Lemon verbena', 'Aloysia triphylla L.', NULL, 'The leaves of lemon verbena are the most economical part of the plant  that can be used anywhere to add a lemony taste in salads, tea, milk, ice  creams and jellies.', 0, 0, NULL),
  (73, 'Stevia', 'Stevia rebaudiana Bertoni L.', NULL, 'It is being cultivated  in Japan, Taiwan, Philippines, Hawaii, Malaysia and overall South  America for food and pharmaceutical products. The property of the  species that called attention to the plant was the intense sweet tests of  the leaves and aqueous extracts.', 0, 0, NULL),
  (74, 'Hibiscus', 'Hibiscus subdariffa L.', NULL, 'Many parts of the plant are of value  with the leaves, seeds and calyces widely used as either food or drug.', 0, 0, NULL),
  (75, 'Lavender', 'Lavandula angustifolia L.', NULL, 'Lavender is a perennial, bushy shrub  growing 0,3 to 1,2 m high and the aromatic evergreen leaves are  completely opposite and up to 5 cm long. It produces essential oil and  the parts used for essential oil distillation are the flowers and leaves.', 0, 0, NULL),
  (76, 'Majoram/Oregano', 'Origanum vulgaris L.', NULL, 'The  use of oregano as medicinal plant is believed to be due to biological  properties of p-cymene and carvacrol. The fresh leaves and dried herb  of oregano as well as essential oil are used medicinally.', 0, 0, NULL),
  (77, 'Sage', 'Salvia officinalis L.', NULL, 'Essential oil of sage is applied in the treatment of a range of diseases  and has been shown to possess antimicrobial, viricidal, cytotoxic,  antimutagenic and antifungal activities.', 0, 0, NULL),
  (78, 'Vanilla', 'Vanilla planifolia', NULL, 'Popular flavoring substance called vanillin, which is mainly used in  flavoring of different food and beverages, and in cosmetics and  perfumery industry, condiments and oleoresin.', 0, 0, NULL),
  (79, 'Basil', 'Ocimum basilicum L.', NULL, 'Basil has been extensively utilized  in food as a flavoring agent, and in perfumery and medical industries', 0, 0, NULL),
  (80, 'Banana', 'Musa paradisiaca var. sapiertum', NULL, 'There are two types of banana, namely dessert and cooking types.  Banana flowers in about 9-12 months and the fruits mature in about 3-4  months. Hence the crop would be ready for harvest in 12 - 16 months  after planting depending on the variety. The yield is roughly 30 - 40  tons/ha.', 0, 0, NULL),
  (81, 'Mango', 'Mangifera indica L.', NULL, 'Mango is a fruit of frost free tropical  and warmer sub-tropical climates. Nowadays it is produced more than  any other fruit crop around the world.', 0, 0, NULL),
  (82, 'Pineapple', 'Ananas comosus', NULL, 'Pineapple is an herbaceous short-lived perennial plant which  grows to 1.0 to 1.5 meters tall. The plant only produces one fruit and  then dies. Commercially suckers that appear around the base are  cultivated', 0, 0, NULL),
  (83, 'Wine grape', 'Vitis vinifera', NULL, 'Grape vines (Vitis vinifera) belong to the genus Vitis. The Genus  includes several species which produce palatable fruits and byproducts, primarily wine. Grapes can be in the form of table grapes and  raisins or dried grapes which are equally important in the international  market.', 0, 0, NULL),
  (84, 'Avocado', 'Persea americana M.

Avocados were first seen in the United States in the early 1800''s.
California is currently the largest producer of avocados stateside. There
are more than 80 varieties, with the "Hass" variety dominating the crop
share. A single mature avocado tree can produce more than 400 pieces
of fruit in a year.Avocados are loaded with nutrients such as dietary fiber, vitamin B6,
vitamin C, vitamin E, potassium, magnesium, and folate. They''re also
cholesterol and sodium free.', 6, 'Avocados are loaded with nutrients such as dietary fiber, vitamin B6,  vitamin C, vitamin E, potassium, magnesium, and folate. They''re also  cholesterol and sodium free. Avocados contain 60% more potassium  per ounce than bananas. This fruit is an excellent source of  monounsaturated fat.', 0, 0, 2),
  (85, 'Date palm', 'Phoenix dactylifera L', NULL, 'Date Palm plays an  important nutritional, economical, religion, cultural and ecological role  in desert and semi desert agro-ecologies of Ethiopia. It is also  historically known that people inhibiting in deserts live on dates and  milk without suffering any nutritional problem.', 0, 0, NULL),
  (86, 'Tree lucerne', 'Chamaecytius spp', NULL, 'Forage', 0, 0, NULL),
  (87, 'Elephant grass', 'Pennisetum purpureum', NULL, 'Forage', 0, 0, NULL),
  (88, 'Rhode', 'Chloris gayana', NULL, 'Forage', 0, 0, NULL),
  (89, 'Panicum', 'Panicum colloratum', NULL, 'Forage', 0, 0, NULL),
  (90, 'Dolicos lablab', 'Lablab purpureus', NULL, 'Forage', 0, 0, NULL),
  (91, 'Phalaries', 'Phalaries aquatica', NULL, 'Forage', 0, 0, NULL),
  (92, 'Trifolium', 'Trifolium quartinianum', NULL, 'Forage', 0, 0, NULL),
  (93, 'Vetch', 'Vicia spp', NULL, 'Forage', 0, 0, NULL),
  (94, 'Cow pea', 'Cowpea unguiculata', NULL, 'Forage', 0, 0, NULL),
  (95, 'Andropogon', 'Andropogon gayanus', 7, 'Forage', 0, 0, NULL),
  (96, 'Pigeon pea', 'Cajanus cajan L.)', NULL, 'Forage', 0, 0, NULL),
  (97, 'Oats', 'Avena sativa', NULL, 'Forage', 2, 2, NULL),
  (98, 'Sesbania', 'Sesbania spp', NULL, 'Pasture', 0, 0, NULL),
  (99, 'Pennisetum polystachion', '0', NULL, 'Pasture', 0, 0, NULL),
  (100, 'Panicum maximum', '0', NULL, 'Forage', 0, 0, NULL),
  (101, 'Lupin', 'Lupinus spp.', NULL, 'It is  an ancient traditional multipurpose crop being cultivated particularly in  the North-western part of Ethiopia. In Ethiopia lupin is believed to  have originated and introduced into Ethiopia from Egypt. It is also  believed that the Amharic local name of lupin in Ethiopia, Gibto, has  been derived from the Amharic name of Egypt, Gibtsi.', 0, 0, NULL),
  (102, 'Alfalfa (Medicago sativa)', 'Medicago sativa', 7, 'Forage', 0, 0, 2),
  (103, 'Pennisetum sphacelatum', '0', NULL, 'Forage', 0, 0, NULL),
  (104, 'Perennial grass', '0', NULL, 'Forage', 0, 0, NULL),
  (105, 'Desho grass', 'Pennisetum glaucifolium', NULL, 'Forage', 0, 0, NULL),
  (106, 'Napier grass', 'Pennisetum purpureum', NULL, 'Forage', 0, 0, NULL),
  (107, 'Local forage legume', 'Local', NULL, 'Forage', 0, 0, NULL),
  (108, 'Mulberry', 'Morus indica', NULL, 'Forage', 0, 0, NULL),
  (109, 'Cotton', 'Gossypium hirsutum', NULL, 'It is used to manufacture a wide variety of of hand woven  dresses and industrial processed textile fabrics, in addition to edible oil  and protein rich-seedcake production for human and animal  consumption respectively.', 0, 0, NULL),
  (110, 'Kenaf', 'Hibiscus spp', NULL, 'Kenaf  is being developed as a non wood fiber crop. The bark, which contains  long soft bast fibers, makes up 30 to 40% of the dry weight of the stem,  is an ideal blend of long short fibers', 0, 0, NULL),
  (111, 'Sugarcane', 'Saccharum officinarum', NULL, 'Sugarcane is the main sugar producing crop in Ethiopia and sugar  industry plays a significant role in the socio economy of the country.', 0, 0, NULL),
  (112, 'Coffee', 'Coffea arabica L.', NULL, 'Coffee is the most important agricultural commodity and beverage  enjoyed throughout the world. Coffee grows at various altitudes,  ranging from 550 to 2750 meters above sea level.', 0, 0, NULL),
  (113, 'Tobaco', 'Nicotiana tabacum', NULL, 'Tobacco is a stimulant and  the dried leaves of the tobacco plant can be cured and used to produces  tobacco cigarettes, cigars and snuff or for pesticide production.', 0, 0, NULL),
  (114, 'Adzuki bean', 'Adzuki bean (Vigna angularis)', 2, 'It is an annual bushy widely grown in  Japan and China for its seeds which are used as food and to produce a  flour', 2, 0, NULL),
  (115, 'Lima bean', 'Lima bean /butter bean (Phaseolus lunatus)', NULL, 'The crop has deep rooted, drought tolerant and  wide environmental adaptation character. It has numerous uses like  animal feed, soil improvement, human food (immature and dry seeds)  and medicine.', 2, 0, NULL),
  (116, 'Lettuce', 'Lactuca sativa', NULL, 'Salad', 2, 0, NULL),
  (117, 'Water melon', 'Citrullus lanatus', NULL, 'Fruit', 2, 0, NULL),
  (118, 'Musk melon', 'Cucumis melo', NULL, 'Fruit', 2, 0, NULL),
  (119, 'Broccoli', 'Brassica oleracea', 5, 'Salad', 2, 0, NULL),
  (120, 'Cauliflower', 'Brassica oleracea', NULL, 'Salad', 2, 0, NULL),
  (121, 'Snap pea', 'Pisum sativum var. macrocarpon', NULL, 'Salad', 2, 0, NULL),
  (122, 'Snow pea', 'Pisum sativum var. saccharatum', NULL, 'Salad', 2, 0, NULL),
